select 'services', $json$[{"id":"svc-web-apps","name":"Web Applications","description":"Build scalable full-stack web applications, with frontend hosting, backend APIs, authentication, storage, and deployment workflows.","category":"web-development","level":"beginner_to_advanced","technologies":["AWS Amplify","Amazon S3","Amazon CloudFront","AWS Lambda"],"delivery_modes":["workshop","guided_lab","community_project"],"audience":["students","beginner_builders","developers"],"outcomes":["Understand web applications fundamentals","Complete a practical exercise or project","Document learning and implementation decisions"],"prerequisites":["Basic programming or cloud concepts"],"is_official_paid_service":false,"record_type":"synthetic_expansion_of_website_learning_theme","status":"example_catalogue_record"},{"id":"svc-ai-ml","name":"AI & Machine Learning","description":"Explore intelligent application features such as chatbots, computer vision, recommendation systems, and predictive analytics.","category":"ai-ml","level":"intermediate","technologies":["Amazon Bedrock","Amazon SageMaker","AWS Lambda","Amazon S3"],"delivery_modes":["workshop","guided_lab","community_project"],"audience":["students","beginner_builders","developers"],"outcomes":["Understand ai & machine learning fundamentals","Complete a practical exercise or project","Document learning and implementation decisions"],"prerequisites":["Basic programming or cloud concepts"],"is_official_paid_service":false,"record_type":"synthetic_expansion_of_website_learning_theme","status":"example_catalogue_record"},{"id":"svc-analytics","name":"Real-Time Analytics","description":"Learn event ingestion, stream processing, data pipelines, and live dashboards for analytics use cases.","category":"data-analytics","level":"intermediate_to_advanced","technologies":["Amazon Kinesis","AWS Lambda","Amazon DynamoDB","Amazon CloudWatch"],"delivery_modes":["workshop","guided_lab","community_project"],"audience":["students","beginner_b