insert into site_config (key, value)
select 'faq', $json$[{"id":"faq-001","question":"What is AWS Student Builder Group?","answer":"AWS SBG is a student-led technical community at Tulas University, Dehradun, where learners build practical cloud skills through projects, workshops, collaboration, and hackathons.","category":"about","keywords":["about","student","builder","group"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-002","question":"Who can join AWS SBG?","answer":"The website invites Tulas students as well as external students, developers, industry professionals, and technology enthusiasts to engage with community activities.","category":"membership","keywords":["membership"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-003","question":"Where is AWS SBG based?","answer":"AWS SBG is based at Tulas University in Dehradun, Uttarakhand, India.","category":"location","keywords":["location","where","based"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-004","question":"Is AWS SBG only for Tulas University students?","answer":"No. The events page says external students, developers, industry professionals, and technology enthusiasts can also suggest or request events.","category":"membership","keywords":["membership","tulas","university","students"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-005","question":"Do I need prior AWS experience?","answer":"The community presents beginner-friendly learning paths, including AWS fundamentals and introductory workshops. Check each event description for its expected level.","category":"eligibility","keywords":["eligibility","prior","experience"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-006","question":"How can I join the community?","answer":"Use the community links on the official website, including the Meetup and WhatsApp community links, or contact the contact page on the website.","category":"joining","keywords":["joining","community"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-007","question":"How can I contact AWS SBG?","answer":"Email the contact page on the website or use the official social and community links listed on awstulas.org.","category":"contact","keywords":["contact"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-008","question":"Where can I find upcoming events?","answer":"Visit https://awstulas.org/events and the official Meetup group. The website says Meetup is the central place for event announcements and RSVPs.","category":"events","keywords":["events","where","upcoming"],"source":"https://awstulas.org/events","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-009","question":"Are upcoming event dates confirmed?","answer":"The events page currently labels upcoming dates as revealing soon. Confirm dates on the official events page or Meetup before making plans.","category":"events","keywords":["events","upcoming","event","dates","confirmed"],"source":"https://awstulas.org/events","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-010","question":"Where are events conducted?","answer":"The website lists Tulas University, campus spaces, and virtual formats for different event examples. Check each event listing for its venue.","category":"events","keywords":["events","where","conducted"],"source":"https://awstulas.org/events","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-011","question":"Can I suggest an event topic?","answer":"Yes. The events page includes an event suggestion form that asks for your name, email, topic, event type, and details.","category":"events","keywords":["events","suggest","event","topic"],"source":"https://awstulas.org/events","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-012","question":"Are events free?","answer":"The website content reviewed does not establish a universal event fee policy. Check the specific event registration information.","category":"pricing","keywords":["pricing","events","free"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-013","question":"Does AWS SBG provide AWS certification?","answer":"The community offers certification preparation guidance and learning resources; certification exams are provided through the official AWS certification process.","category":"certification","keywords":["certification","provide"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-014","question":"Where can I learn AWS for free?","answer":"The Learning Hub links to AWS Skill Builder, AWS Educate, certification resources, project starter kits, and community learning material.","category":"learning","keywords":["learning","where","learn","free"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-015","question":"What is the builder journey?","answer":"The website describes a path from joining the group to AWS fundamentals, workshops, cloud projects, hackathons, certifications, leadership, and career opportunities.","category":"learning","keywords":["learning","builder","journey"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-016","question":"What technologies can members explore?","answer":"The website lists services and technologies including EC2, S3, Lambda, CloudFront, IAM, DynamoDB, ECS, EKS, Amplify, SageMaker, CloudWatch, and API Gateway.","category":"technology","keywords":["technology","technologies","members","explore"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-017","question":"Does AWS SBG teach AI and machine learning?","answer":"Yes. The website highlights AI and machine learning projects such as chatbots, computer vision, and predictive analytics.","category":"technology","keywords":["technology","teach","machine","learning"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-018","question":"Can beginners participate in hackathons?","answer":"The community promotes learning and building together. Review the individual challenge requirements and team rules before registering.","category":"hackathons","keywords":["hackathons","beginners","participate"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-019","question":"Does the group offer mentorship?","answer":"The community describes mentorship, peer learning, code reviews, and networking as part of its community activities.","category":"community","keywords":["community","group","offer","mentorship"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-020","question":"Can external developers attend sessions?","answer":"The events page says the community is open to external students, developers, industry professionals, and tech enthusiasts for event suggestions or requests. Check individual event eligibility.","category":"membership","keywords":["membership","external","developers","attend","sessions"],"source":"https://awstulas.org/events","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-021","question":"Where is the Learning Hub?","answer":"Visit https://awstulas.org/learning-hub for curated AWS learning resources and project guidance.","category":"learning","keywords":["learning","where"],"source":"https://awstulas.org/events","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-022","question":"What is AWS Skill Builder?","answer":"AWS Skill Builder is an official AWS learning platform linked from the AWS SBG Learning Hub. Visit https://skillbuilder.aws/ for current courses and learning plans.","category":"resources","keywords":["resources","skill","builder"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-023","question":"What is AWS Educate?","answer":"AWS Educate is an AWS learning resource linked from the community Learning Hub for students exploring cloud skills.","category":"resources","keywords":["resources","educate"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-024","question":"Does AWS SBG help with projects?","answer":"The website emphasizes building real-world applications, deploying projects, collaborating, and creating portfolio-ready work.","category":"projects","keywords":["projects"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-025","question":"Can I collaborate with other students?","answer":"Yes. Community building, peer learning, study groups, code reviews, and collaborative projects are core themes of AWS SBG.","category":"community","keywords":["community","collaborate","other","students"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-026","question":"Does AWS SBG have a team page?","answer":"The website has a Team section, but the homepage currently indicates that the 2026 cohort details are being revealed soon.","category":"team","keywords":["team","page"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-027","question":"Who are the current team members?","answer":"The public homepage reviewed does not provide a complete verified team roster. Check the official Team page or community announcements for updates.","category":"team","keywords":["team","current","members"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-028","question":"What is the official email address?","answer":"The website lists the contact page on the website as the community contact email.","category":"contact","keywords":["contact","official","email","address"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-029","question":"What is the official website?","answer":"The official website is https://awstulas.org/.","category":"contact","keywords":["contact","official","website"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-030","question":"What is the community mission?","answer":"The community's stated mission is to make cloud computing accessible, practical, and exciting through hands-on learning and building.","category":"about","keywords":["about","community","mission"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-031","question":"What are the six pillars of AWS SBG?","answer":"The six pillars are Cloud Learning, Build Projects, Community, Hackathons, Certifications, and Career Growth.","category":"about","keywords":["about","pillars"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-032","question":"Does AWS SBG cover DevOps?","answer":"Yes. The website describes DevOps and infrastructure topics including CI/CD, container orchestration, and infrastructure as code.","category":"technology","keywords":["technology","cover","devops"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-033","question":"Does AWS SBG cover cloud security?","answer":"Yes. Cloud security is one of the learning themes, including identity management, threat detection, and compliance automation.","category":"technology","keywords":["technology","cover","cloud","security"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-034","question":"Can I access AWS resources through the website?","answer":"The Learning Hub links to AWS training, certification guidance, AWS Educate, project starter kits, and community articles.","category":"resources","keywords":["resources","access","through","website"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-035","question":"Is AWS SBG an official AWS certification provider?","answer":"The website describes a student-led AWS-focused community. It does not claim to be an AWS certification exam provider.","category":"clarification","keywords":["clarification","official","certification","provider"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-036","question":"What is the difference between a workshop and a hackathon?","answer":"A workshop focuses on guided learning and practice, while a hackathon is a team-based challenge to design and build a solution within a limited time.","category":"events","keywords":["events","difference","between","workshop","hackathon"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-037","question":"How do I register for an event?","answer":"Use the registration link on the event listing when available, and follow the event's official instructions. Some listings may still show dates or registration details as forthcoming.","category":"events","keywords":["events","register","event"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-038","question":"Are online events available?","answer":"The events page includes virtual event examples. Check the specific event listing for its delivery mode and joining instructions.","category":"events","keywords":["events","online","available"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-039","question":"Can I get a certificate for attending?","answer":"Certificate availability is not guaranteed across all events by the website content reviewed. Check the event-specific announcement.","category":"certificates","keywords":["certificates","certificate","attending"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"},{"id":"faq-040","question":"How can I stay updated?","answer":"Follow the official Meetup and social links listed on awstulas.org and check the Events page for announcements.","category":"updates","keywords":["updates","updated"],"source":"https://awstulas.org/","confidence":"website_based_with_qualification","last_reviewed":"2026-11-20"}]$json$
